def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    last_m, last_o = history[-1]
    if n >= 99:
        return 'D'
    if n <= 3:
        return 'D' if last_o == 'D' else 'C'

    mine = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_d = sum(1 for x in opp if x == 'D')
    my_d = sum(1 for x in mine if x == 'D')

    w = 10 if n > 10 else n
    rec_opp_d = sum(1 for h in history[-w:] if h[1] == 'D')

    opp_streak = 0
    for h in reversed(history):
        if h[1] == 'D':
            opp_streak += 1
        else:
            break

    my_streak = 0
    for h in reversed(history):
        if h[0] == 'D':
            my_streak += 1
        else:
            break

    forg = 0
    retal = 0
    sucker = 0
    cc_n = 0
    cd_n = 0
    cc_c = 0
    cd_c = 0

    for i in range(1, n):
        if mine[i - 1] == 'C':
            cc_n += 1
            if opp[i] == 'C':
                cc_c += 1
            else:
                sucker += 1
        else:
            cd_n += 1
            if opp[i] == 'C':
                cd_c += 1
                forg += 1
            else:
                retal += 1

    opp_c = n - opp_d
    opp_rate = opp_c / n

    rate_c_my_c = cc_c / cc_n if cc_n >= 4 else 1.0
    rate_c_my_d = cd_c / cd_n if cd_n >= 4 else rate_c_my_c

    unresponsive = cc_n >= 8 and cd_n >= 8 and abs(rate_c_my_c - rate_c_my_d) < 0.12
    responsive = cc_n >= 6 and cd_n >= 6 and rate_c_my_c > rate_c_my_d + 0.18

    hostile = opp_d > n * 0.45 or rec_opp_d >= max(4, w * 0.6) or opp_streak >= 3

    low_limit = max(1, int(n * 0.04))
    cap = max(8, int(n * 0.15))
    if retal == 0 and opp_d <= low_limit and forg >= 5:
        cap = max(cap, min(50, int(n * 0.45)))

    if last_m == 'D' and last_o == 'D':
        if hostile or opp_d > n * 0.55 or opp_streak >= 3 or sucker > n * 0.2:
            return 'D'
        if my_streak >= 3 and opp_rate < 0.55:
            return 'D'
        return 'C'

    if last_o == 'D':
        if n >= 88:
            return 'D'
        if hostile or opp_streak >= 2 or sucker >= max(2, int(n * 0.12)) or rec_opp_d >= max(3, w * 0.5):
            return 'D'
        if opp_d <= low_limit and sucker <= 1 and opp_rate > 0.72 and not responsive:
            return 'C'
        return 'D'

    if last_m == 'D':
        if not hostile and opp_d <= low_limit and my_d < cap and n >= 12:
            return 'D'
        if unresponsive and opp_rate > 0.55 and my_d < cap:
            return 'D'
        return 'C'

    if unresponsive and opp_rate < 0.85 and my_d < cap:
        return 'D'

    if n >= 95 and not hostile and opp_rate > 0.9 and opp_d <= low_limit and (opp_d == 0 or (forg >= 3 and retal == 0)) and my_d < 60:
        return 'D'

    if n == 40 and my_d == 0 and opp_d == 0 and not hostile:
        return 'D'

    if n >= 20 and not hostile and opp_d <= low_limit and my_d < cap:
        if my_d == 0 and opp_d == 0:
            if rng.random() < 0.01:
                return 'D'
        elif forg >= 3 and forg > retal * 2:
            if n % 13 == 0 or rng.random() < 0.06:
                return 'D'
        elif unresponsive and opp_rate > 0.6:
            if n % 7 == 0 or rng.random() < 0.04:
                return 'D'

    return 'C'
